struct Node { int val; Node* next; };
std::atomic<Node*> head{nullptr};

void push(int x) {
  Node* n = new Node{x, head.load()};
  while (!head.compare_exchange_weak(
           n->next, n)) {}
}

Node* pop() {
  Node* old = head.load();
  while (old && !head.compare_exchange_weak(
                   old, old->next)) {}
  return old;
}
// head -> A -> B -> C
// T1: old = A, old->next = B, preempted
// T2: pop A, pop B, delete B, push A
// T1 resumes: CAS(head, A, B)

